/// <summary>
/// Free Item Excise Claim Service Controller
/// </summary>
[SysOperationJournaledParametersAttribute(true)]
public class METFreeItemExciseClaimController extends SysOperationServiceController
{
}

Method.Source:
    /// <summary>
    /// select the service class
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METFreeItemExciseClaimService));
        this.parmMethodName(methodStr(METFreeItemExciseClaimService, processOperation));
        this.parmExecutionMode(SysOperationExecutionMode::Synchronous);
        this.parmDialogCaption("@MET:METFreeItemExciseClaimMenuItem");
    }

/// <summary>
/// Automatically populates the batch text required by user before submitting to batch
/// </summary>
/// <returns>caption</returns>
public ClassDescription caption()
{
    return "@MET:METFreeItemExciseClaimMenuItem";
}

    /// <summary>
    /// Main method required to run the opration
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METFreeItemExciseClaimController controller;

        controller = new METFreeItemExciseClaimController();
        controller.parmArgs(args);

        controller.startOperation();
        
    }

/// <summary>
/// BP to have a constructor for new controller.
/// </summary>
/// <returns>Controller instance</returns>
public static METFreeItemExciseClaimController construct()
{
    return new METFreeItemExciseClaimController();
}
